recap:
O **parâmetro** é o espaço do ingrediente na receita. O **argumento** é o ingrediente que você põe nesse espaço ao chamar a função.

```javascript
function pedir(sabor) {
  console.log(`Suco de ${sabor}`);
}

pedir('uva');
// Suco de uva
```

exercises.solution:
function chamarSenha(numero) {
  console.log(`Senha ${numero}, vá ao caixa`);
}

chamarSenha(12);
chamarSenha(13);

function mostrarPesagem(quilos, precoDoQuilo) {
  const total = quilos * precoDoQuilo;
  console.log(`${quilos} kg: R$ ${total.toFixed(2)}`);
}

mostrarPesagem(1.5, 9);
mostrarPesagem(2, 4.75);

function mostrarTreino(aluno, series, repeticoes) {
  const total = series * repeticoes;
  console.log(`${aluno}: ${series} x ${repeticoes} = ${total} repetições`);
}

mostrarTreino('Bia', 3, 12);
mostrarTreino('Caio', 4, 10);
mostrarTreino('Duda', 2, 15);

